--!strict
local Config=require(game:GetService("ReplicatedStorage").Modules.RankConfig);local Profiles=require(script.Parent.PlayerProfileService);local Service={}
function Service.Resolve(points:number):any local found=Config.Tiers[1];for _,tier in Config.Tiers do if points>=tier.MinimumPoints then found=tier else break end end;return found end
local function divisionNumber(value:string):number return value=="I" and 1 or value=="II" and 2 or 3 end
function Service.Display(points:number):string local t=Service.Resolve(points);return t.Name..(t.Division~="" and " "..t.Division or "")end
function Service.Apply(p:Player,place:number,total:number,finished:boolean):any local profile=Profiles.GetProfile(p);if not profile then return {delta=0,oldRank="--",newRank="--",total=0} end;local ranked=profile.RankedRace;local old=Service.Display(ranked.RankPoints);local changes=Config.PointsByPlayers[math.clamp(total,2,8)] or {0};local delta=changes[math.min(place,#changes)] or -5;if not finished then delta=math.min(delta,-3) end;if place==1 then ranked.WinStreak+=1;ranked.RankedWins+=1;if ranked.WinStreak>1 then delta+=Config.WinStreakBonus end else ranked.WinStreak=0 end;ranked.RankedMatches+=1;if place<=3 then ranked.RankedTopThree+=1 end;ranked.RankPoints=math.max(0,ranked.RankPoints+delta);ranked.BestRankPoints=math.max(ranked.BestRankPoints,ranked.RankPoints);local tier=Service.Resolve(ranked.RankPoints);ranked.RankId=tier.Id;ranked.Division=divisionNumber(tier.Division);Profiles.MarkDirty(p);return {delta=delta,oldRank=old,newRank=Service.Display(ranked.RankPoints),total=ranked.RankPoints,promoted=old~=Service.Display(ranked.RankPoints)} end
return Service
